-    let note = cps.find("OPEN HAZARD (#1614)").unwrap_or_else(|| panic!("carvera.cps: the open-hazard note is missing"));
-    let order = cps.find("if (changedAt)").unwrap_or_else(|| panic!("carvera.cps: the M6 order branch is missing"));
